      "paragraph_starts": [
        {"text": "Dufrenne, Wahl, Hyppolite, Lévinas, Merleau-Ponty, Birault - dans leurs cours au moins", "continues_from_previous": false, "continues_to_next": false},
        {"text": "« Une nouvelle ontologie formelle apparaît où la réduction au temps est perpétuellement", "continues_from_previous": false, "continues_to_next": false}
