      "paragraph_starts": [
        {"text": "dans le néo-platonisme et particulièrement dans l'« hénologie » plotinienne", "continues_from_previous": false, "continues_to_next": false},
        {"text": "Qu'on le baptise « école d'Aubenque » ou de toute autre façon, un foyer", "continues_from_previous": false, "continues_to_next": false},
        {"text": "Alors qu'en matière d'histoire de la métaphysique la première réception a comporté", "continues_from_previous": false, "continues_to_next": false}
